{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "anyrouter": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "AnyRouter",
      "options": {
        "baseURL": "https://anyrouter.dev/api/v1",
        "apiKey": "{env:ANYROUTER_API_KEY}"
      },
      "models": {
        "anthropic/claude-sonnet-4-6": {
          "name": "Claude Sonnet 4.6"
        }
      }
    }
  },
  "model": "anyrouter/anthropic/claude-sonnet-4-6"
}

import { query } from "@anthropic-ai/claude-agent-sdk"

for await (const message of query({
  prompt: "List the files here and summarize the project.",
  options: {
    model: "anyrouter/auto",
    env: {
      ...process.env,
      ANTHROPIC_BASE_URL: "https://anyrouter.dev/api",
      ANTHROPIC_API_KEY: process.env.ANYROUTER_API_KEY ?? "",
    },
  },
})) {
  if (message.type === "result") console.log(message.result)
}

{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "anyrouter": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "AnyRouter",
      "options": {
        "baseURL": "https://anyrouter.dev/api/v1",
        "apiKey": "{env:ANYROUTER_API_KEY}"
      },
      "models": {
        "google/gemma-4-31b:free": { "name": "Gemma 4 31B (free)" }
      }
    }
  },
  "model": "anyrouter/google/gemma-4-31b:free"
}

import OpenAI from "openai"

const client = new OpenAI({
  baseURL: "https://anyrouter.dev/api/v1",
  apiKey: process.env.ANYROUTER_API_KEY,
})

const res = await client.chat.completions.create({
  model: "anyrouter/free",
  messages: [{ role: "user", content: "Say hello in one sentence." }],
})
console.log(res.choices[0]?.message.content)

import { createAnyRouter } from "@anyr/ai-sdk-provider"
import { streamText } from "ai"

const anyrouter = createAnyRouter()

const result = streamText({
  model: anyrouter("anyrouter/free"),
  system: "You are a friendly help bot for my project.",
  prompt: "How do I reset my password?",
})

for await (const textPart of result.textStream) {
  process.stdout.write(textPart)
}

