import { createAnyRouter } from "@anyr/ai-sdk-provider"
import { generateText } from "ai"

const anyrouter = createAnyRouter()
const models = ["openai/gpt-5.4-mini", "anthropic/claude-sonnet-4-6", "z-ai/glm-4.7-flash"]

for (const id of models) {
  const started = Date.now()
  const { text, usage } = await generateText({
    model: anyrouter(id),
    prompt: "Summarize the CAP theorem in two sentences.",
  })
  console.log(id, Date.now() - started, "ms", usage.totalTokens, "tokens\n", text)
}

import { createAnyRouter } from "@anyr/ai-sdk-provider"
import { generateText } from "ai"

const anyrouter = createAnyRouter()

const { text } = await generateText({
  model: anyrouter("openai/gpt-5.4-mini"),
  prompt: "Plan the next step.",
  providerOptions: {
    anyrouter: {
      extraBody: { models: ["anthropic/claude-sonnet-4-6", "z-ai/glm-4.7-flash"] },
    },
  },
})
console.log(text)
